def diagram(name,title,steps,foot):
 # Straight vertical reading flow, sufficient room for full Chinese labels.
 height=130+len(steps)*132+90
 out=[f'<svg xmlns="http://www.w3.org/2000/svg" width="900" height="{height}" viewBox="0 0 900 {height}" role="img" aria-label="{h(title)}"><rect width="900" height="{height}" fill="#f5f6f1"/><style>text{{font-family:Arial,PingFang SC,Microsoft YaHei,sans-serif;fill:#203f38}}.title{{font-size:29px;font-weight:700}}.head{{font-size:22px;font-weight:700}}.body{{font-size:17px}}</style><text class="title" x="40" y="49">{h(title)}</text>']
 for i,(title,desc) in enumerate(steps):
  y=80+i*132;out += [f'<rect x="40" y="{y}" width="820" height="110" rx="12" fill="white" stroke="#ccdbd0"/><circle cx="74" cy="{y+34}" r="17" fill="#186d55"/><text x="74" y="{y+40}" text-anchor="middle" style="fill:white;font-size:17px">{i+1}</text><text class="head" x="105" y="{y+40}">{h(title)}</text>']
  for j,line in enumerate(textwrap.wrap(desc,43)):out.append(f'<text class="body" x="105" y="{y+72+j*23}">{h(line)}</text>')
  if i<len(steps)-1:out.append(f'<path d="M450 {y+112}v17m-5-5 5 5 5-5" stroke="#186d55" fill="none"/>')
 for j,l in enumerate(textwrap.wrap(foot,48)):out.append(f'<text class="body" x="40" y="{height-65+j*25}">{h(l)}</text>')
 out.append('</svg>');(A/'diagrams'/f'{name}.svg').write_text(''.join(out))
