body=sec('starting-point','2.1 先问人在何处，再看合法身份',table(['目前状态','可以优先研究','关键阻碍'],[['中国大陆，无加拿大身份','海外可行的乡村职位、具备联邦资格后的省快速通道选择、合格雇主工签；留学为另一条成本更高路径','机会类别需要已在阿省工作；旅游类别需要特定工签及本地连续工作'],['第三国有合法工作经历','先核职责、工资、工作时长证明、学历认证和联邦资格；乡村可用符合规则的境外经验','第三国身份不自动赋予加拿大工作权；不同国的证明和无犯罪材料可能增加准备时间'],['加拿大其他省工作','阿省真实职位、迁居意图、工签许可地点/雇主；乡村境外阿省申请职业只限0—3级','不能把其他省0—5级职位直接复制为阿省境外乡村方案'],['阿省有效毕业工签','学历类型、专业与工作关联、6个月工作、职业及雇主；乡村另外核社区和经验豁免','某些短证书虽有毕业工签资格，却不符合机会类别的学历要求'],['阿省雇主专属工签','检查实际许可依据及到期日；机会、乡村、旅游的差异规则','换雇主不等于立刻可上岗；维持身份在机会/旅游类别不被接受'],['加拿大访客或失去身份','先核合法身份恢复/离境和未来签证方案','访客不能直接工作；在加拿大无有效工签者不能用乡村类别绕过规则']])+c('abos')+c('abrural')+c('abtour')+c('work-permit'))
body+=sec('profiles','2.2 研究用差异化背景：从政府规则反推产品适配',table(['虚构背景','可研究的顺序','硬门槛与停止点'],[['22岁，高中，英语弱，年预算8万元人民币','国内提升语言与获得可证明技能；再查真实雇主机会','预算不支持普通国际留学全年总支出；先不卖留学移民套餐'],['29岁，大专，6年厨师，英语约基础水平','核63200真实职责→语言→乡村雇主/工签可行性→本地工作后再看机会或旅游','乡村和旅游不同；买职位不合法也不可依赖；旅游要合格工签和同雇主6个月'],['34岁，本科机械，8年设备工作，已在第三国','用具体职责比对技术员/工程师/技工→学历和执照→雇主→联邦或阿省类别','工程学历不等于阿省工程师执照；技术员和技工是不同职业路径'],['26岁，阿省两年幼教文凭，毕业工签有效','取得二/三级幼教认证→真实相关职位→满经验→意向表达','幼教不属于专设医疗九类；无证或一级不符合机会类别相应要求'],['38岁，国内护士，英语中等，有家庭','监管机构先评估→补语言/学历和执业资格→真实医疗职位→专设医疗分支','原有护理基础可研究；零基础读高要求护理不应被包装为低门槛'],['42岁，企业经营10年，净资产充足，愿长期乡村经营','商业真实性→社区→资金来源→乡村企业家申请与履约','至少投资、净资产和家庭储备分开；不能把卖房后的全部资金都用于最低投资'],['31岁，软件本科、4年开发经验','核44职业及雇主行业双清单→联邦资格→科技子通路','在普通餐馆做网站开发，不会因为职称是程序员就满足科技雇主行业条件']]))
body+=sec('product','2.3 不编造“就业率/移民率”',p('这里的“较适配”是规则匹配判断，不是个案成功率。学校公布的毕业生就业统计通常包含本地学生、回复样本及不同岗位，不能等同于中国留学生就业概率。省邀请轮次没有对应全部符合条件人群的可靠分母，不能相除算移民率。')+table(['内部评估项','要收集的可验证证据'],[['就业可行性','近30天同地区真实招聘、职责、工资、执照、可接受身份、雇主面试反馈；按日期留存。'],['移民可行性','硬门槛逐项通过、真实分数、近期省选择重点、名额与身份缓冲。'],['资金承受力','学费、生活、保险、材料、空窗期、家属和退出费用；工作收入只能作为不确定项。'],['产品停止点','资格缺口无法弥补、资金不足、雇主不真实、主要目标只能依赖未公布政策时暂停收费推进。']]))
page('02-fit.html',CHAPTERS[2][1],'人物是检验框架的例子；每次咨询先核身份、实际经历、语言、资金和家庭约束。',body)

body=sec('worker-common','3.1 工人申请共同规则与雇主审查',table(['项目','现行要求与准备'],[['申请顺序','满足类别→提交WEOI→省邀请→建立申请→交完整材料和费用→决定。入池不是省申请，也不是工签申请。'],['职位','真实、有工资、每周至少30小时，原则上至少12个月；签名的雇佣合同、职责、工资、地点、双方信息。专设医疗个别合同/兼职等例外另按其规则核。'],['企业','阿省持续实际经营至少2个完整财政年度；通常上年总收入至少400,000、至少3个全职等值员工。政府与原住民机构等有例外；低于门槛时按经营年数限制可支持人数，不是一概拒绝。'],['工资','满足最低工资和职位/地区适用最低起薪标准；有LMIA时遵守其核定工资。不能只用省最低工资代替职业要求。'],['不合格安排','独立承包、季节/临时零工、部分派遣、所有者或董事持股等不合格关系、无真实营业场所、人在境外远程等按类别审查。'],['雇主资料','营业与注册、税务收入、员工人数、工伤保险、招聘、工资工时、联系人和支持表；雇主拒绝配合意味着路径不能成立。'],['工作授权','先核工签类别、雇主/地点限制、有效期和当前实际工作；不同类别对维持身份规则不同。']])+c('employers')+c('worker-docs')+c('worker-apply'))
body+=sec('aos','3.2 阿尔伯塔机会类别：人在阿省工作是前提',table(['维度','具体规则'],[['居住与工签','递交及审理时在阿省合法居住、实际工作，持有效合格工签。维持身份或等待恢复身份不被本类别接受。'],['合格工签范围','正面LMIA；指定国际协议、跨国调动、国际经验、法语流动、宗教工作等豁免；受虐工人及适用家庭成员；符合条件的阿省毕业工签；指定临时公共政策。普通配偶开放工签不可笼统认为符合。'],['工作经验','当前职业：最近18个月阿省至少12个月，或最近30个月加拿大/境外至少24个月；合格阿省毕业工签持有人最近18个月阿省至少6个月。一般每周30小时。'],['经历排除','原则上不计在加拿大在读期间经验；特定有薪阿省合作实习例外必须逐项核，不把所有学生打工计入。'],['职业','多数TEER 0—5可研究，但34项排除清单及星号范围必须核。幼教须二级/三级；强制认证技工须合格资格。'],['语言','TEER 0—3通常CLB/NCLC 5，4—5通常4；33102护理辅助人员要求7。考试四项分别达标且提交时不超过2年。'],['学历','至少加拿大高中或同等；境外学历一般需ECA，合格加拿大文凭/学位或特定认可技工资格有豁免。'],['毕业工签学历','须阿省合格公立高等教育、获批准资格。普通文凭通常至少2年；一年制须属于合格的文凭后/学士后证书等类别；不能把新入读普通一年短证书当通用合格学历。'],['专业关联','毕业工签持有人的当前工作须与阿省所学相关。2019年4月起入读的一年文凭后/学士后课程，还需核工作与境外原有高等教育领域的关联。']])+c('abos')+p('<a href="occupations.html#abos">打开34项完整排除清单及星号例外</a>'))
body+=sec('ee','3.3 省快速通道与科技、执法子通路',table(['分支','额外条件','怎样准备'],[['基础资格','有效EE档案，先符合FSW、FST或CEC其中一类；CRS至少300、居住阿省意图及省级选择条件。','联邦档案与省意向表达一致；职业职责、语言、学历认证、经验和资金按联邦类别分别核。'],['加速科技','44个职业代码之一，且雇主主业属于27个行业代码之一；阿省合格工作/职位与联邦档案主要职业一致；在阿省工作者核合法身份。','同时核人做什么、公司做什么；雇主确认行业，职位职责支持职业码，不能只抄招聘标题。'],['执法','经阿省警察局长协会认定的国际招聘；协会成员警务雇主；40040、41310、42100之一。','须获特定警务雇主真实招聘支持；国内警察经历不等于直接转执照或获提名。'],['2026重点选择','医疗、科技、建筑、制造、航空、农业、指定乡村等按当前省容量页观察。','“重点行业”是选择方向，省未为全部领域公布固定完整职业白名单，不自行编一个。']])+c('abee')+c('ee-selection')+c('abtechlist')+c('abtechindustry')+c('processing')+note('来源差异：部分旧网页仍出现科技网页表单/早期选择年份；当前工人统一申请页采用意向表达和邀请机制。实际提交按当前官方门户指引，保存差异；不要同时重复创建冲突申请。'+c('worker-apply'),True))
body+=sec('health','3.4 专设医疗：九类专业，不是所有医院工作',table(['问题','规则'],[['职业范围','医生、注册护士、执业护士、高阶执业护士、医师助理、作业治疗师、物理治疗师、临床社会工作者、心理学家。护工、清洁、厨师、幼教不能因在医疗/照护场所工作而自动加入。'],['监管门槛','必须有相应监管机构认可的最低执业能力证明及合格阿省医疗雇主工作邀请；不仅是国内毕业证。'],['快速通道分支','能满足联邦快速通道及阿省该分支者应走此分支；联邦档案、职业、CRS及省要求共同核。'],['非快速通道分支','仅不符合快速通道时研究；语言通常CLB 5或按已满足注册的规定证明；执业护士和临床社会工作者有特别语言文件要求。'],['工签与雇主差异','已在阿省工作者按医疗通路允许的合法身份条件核，不能机械套用机会类别禁止维持身份的规则；医疗聘用合同和按服务收费等按该页具体例外。'],['2026监管变化','健康护理助理自2026-02-02成为受监管职业，不能继续用“无需注册”的旧介绍；这并不把它加入专设医疗九类。']])+c('abhealth')+c('health-regulators')+c('hca-regulation'))
body+=sec('rural','3.5 乡村振兴：境外与境内可选职业不同',table(['维度','现行规则'],[['职位和背书','指定社区真实、全职、非季节性职位；由经济发展组织签发候选人背书信，通常有效1年；递交意向表达时已经取得。'],['所在地限制','住阿省且持有效工签者可研究TEER 0—5；住阿省之外，包括中国、第三国或加拿大其他省，只接受TEER 0—3职位。加拿大境内无有效工签者不符合。'],['经验','最近18个月至少12个月全职，允许符合规定的阿省/加拿大/境外组合；工作经验等级须满足职位等级对应表。指定社区合格学习机构两年课程毕业且持毕业工签者有特定12个月经验豁免。'],['语言、学历','职业0—3为CLB/NCLC 5，4—5为4；至少高中，境外学历通常需认证；执照及二/三级幼教认证另核。'],['资金','境外或加拿大境内未工作者须安家资金；按家庭人数和社区人口表计算，房产车辆不算可用现金。'],['名单','17项不合格职业，星号只排除对应子职业；不等于机会类别34项。'],['社区运营','省指定不等于社区当天接受候选人，也不等于所有雇主有资格；复核社区窗口、雇主、当地优先职业及背书流程。']])+c('abrural')+c('communities')+table(['职位等级','可计工作经历等级'],[['0','0或1'],['1','0、1或2'],['2或3','1、2、3或4'],['4','2、3、4或5'],['5','5且同一职业代码']])+table(['家庭人数','社区少于1,000人','1,000—30,000人','30,000—99,999人'],TABLES['abrural'][3][2:])+p('上表为官网本轮留存值；申请前重新核对。不得用学签生活费门槛替代社区安家资金表。'))
body+=sec('tour','3.6 旅游与酒店：不能只看职业在表内',table(['维度','要求'],[['工作许可','有效LMIA工签，或明确允许的阿省野火特别工签；维持身份及其他工签不能直接套用。'],['经历','在阿省、同一当前雇主、合格职业，至少连续6个月且780小时；全职最低每周30小时。'],['职业','18个正面职业名单，包括部分酒店、餐饮、旅游及清洁岗位。'],['雇主','主业符合指定工伤保险行业，且符合指定行业协会会员规则；无法加入时按网页特定旅游体验提供商例外核。'],['其他','至少高中及所需学历认证；CLB/NCLC 4；真实全职职位和雇主文件。'],['留学产品边界','持毕业工签的毕业生不能直接拿“同雇主6个月”当本类别方案；先核其工签是否符合，本地符合条件者也可比较机会类别。']])+c('abtour')+p('<a href="occupations.html#abtour">完整18职业、20行业与14协会列表</a>'))
body+=sec('score','3.7 100分工人评分表：自报分数要有证据',fig('scoring','图3：资格、分数与选择的关系','图中分数不是获邀线。',c('points'))+table(['因素','分值细则','上限'],POINTS)+p('家庭联系旧规则：2025-01-29及以前提交并已申报祖父母、叔舅姑姨、侄甥等分数的现有意向表达有过渡处理；不要把它用于新建档案。官方按英语/法语最低单项评分；不以平均分代替。'+c('points')))
for anchor,title,k,rs in BUSINESS:body+=sec(anchor,'3.8 '+title,table(['项目','准备与边界'],rs)+c(k)+c({'abbiz':'res-apply','abgradbiz':'ges-apply','abforeigncriteria':'fges-apply','abfarm':'farm-apply'}[k]))
body+=sec('federal','3.9 最后接哪条联邦通路',table(['联邦层','关键资格','不能误解'],[['FSW','过去10年内至少1年连续合格技术工作、CLB 7、学历/认证、67分资格筛选及所需资金。','67是资格筛选分，300是阿省省级最低综合排名条件，工人100分又是另一套。'],['CEC','过去3年内至少1年合法加拿大技术工作；0/1级语言7、2/3级语言5；全日制在读及一般自雇经验不计入。','做了任何工作一年不等于都符合。'],['FST','过去5年内2年合格技工经验；至少1年有效工作邀请或加拿大合格技工资格证；口听5、读写4等联邦条件。','在名单里不等于已持合格证书；类别职业范围要核。'],['快速通道省提名','满足相应联邦类别并接受合格增强提名，可获得额外600综合排名分。','省意向表达、获邀或申请中都不等于已经获得600分。'],['非快速通道省提名','使用非快速通道省提名联邦申请流程，提交提名、身份家庭及准入文件。','不用快速通道不等于不用语言/材料或没有联邦审查。']])+c('fsw')+c('cec')+c('fst')+c('pnp'))
page('03-rules.html',CHAPTERS[3][1],'把工签、经验、职业、雇主、语言、学历、资金和联邦衔接分别检查。',body)
body=sec('study-gates','4.1 留学不是一个移民类别：先过五道门',fig('study-path','图4：境外客户的逐关路径','箭头表示条件顺序，不代表每一步一定成功。',c('abos')+c('pgwp'))+table(['检查点','必须回答的问题','停止条件'],[['学校','是否在DLI名单？公立还是私立？实际授课校园和合作安排是什么？','仅整校有编号不能证明具体课程可获毕业工签'],['课程','学位/文凭/普通证书/文凭后证书分别是什么？学制、CIP、全日制与线下要求？','普通一年证书不能直接套用机会类别毕业生学历要求'],['个人','以前是否用过毕业工签？学签申请日期、护照效期、学习方式是否符合？','课程合格不代表个人必然合格'],['工作','毕业能做什么真实职业？须什么证照？工作是否与所学和原有专业相关？','没有可实现的上岗方案，先不签长期开销'],['省与联邦','工作经验、雇主、语言及选择规则都满足吗？工签到期前可否衔接？','只能靠未来放宽或未公布项目时，不能卖成确定方案']])+c('dli')+c('pgwp')+c('cip')+c('abos'))
body+=sec('education','4.2 不同教育背景，选择方式不同',table(['国内背景','可以研究的课程','必须核清'],[['高中/中专','两年公立文凭；专业基础、国际学历等值及英语先修','中专不自动等于所有课程所需高中数学、化学、生物；先做学校正式评估'],['大专','相关领域两年文凭或合格文凭后项目','需要什么前置学历、是否属于省认可的文凭后证书；不是任何“研文”营销名称都合格'],['普通本科','与原专业或已有工作有合理联系的进阶课程','一年文凭后/学士后项目特别注意机会类别对原境外专业关联的要求；转专业需有真实学习逻辑'],['已有专业执照/多年技术经验','先比较直接资格认定与招聘；读书可能只是补缺口','不要让能通过监管评估的人重复读全套学历；但国内证书不能自动上岗'],['已读加拿大院校','先看剩余工签/曾用毕业工签/转校和全日制记录','毕业工签通常不能重复申请；再读书不保证再得一张新工签']]))
