body+=sec('budget','4.4 用现金流决定是否继续，而不是先卖房',p('以下是<b>单人、第一年、2026-09-24核对的学校估费＋联邦生活资金底线</b>。自2026-09-01适用的单人生活资金为23,448加元，不含学费和往返交通。实际生活、住房和家属费用可以更高。汇率5.2仅作算例，不是实时汇率。'+c('study-funds'))+table(['项目','首年学校学杂费','生活资金底线','合计（仍不含交通等）','人民币算例'],[['诺奎斯特幼教文凭前2学期','19,807.84','23,448','43,255.84','约22.49万元'],['南阿尔伯塔理工学院软件文凭','25,824.50','23,448','49,272.50','约25.62万元'],['奥兹学院农业管理第一年前2学期','19,171.74','23,448','42,619.74','约22.16万元']])+c('school-ece-cost')+c('school-software')+c('olds-fees-pdf')+note('如果仍坚持“全年总支出8万元人民币、每月净存1万元人民币”，普通国际留学路线目前不匹配这个预算；应先研究真实雇主招聘和自身可转移技能。不能把尚未获得的兼职工资抵销必须准备的学费与生活资金。',True)+ul(['完整预算另列：申请费、语言考试、翻译与学历认证、签证与生物识别、体检、保险、书本工具、押金、机票、空窗期。','已婚有孩子的客户分别核随行资格、配偶工作许可与孩子教育，不把单人资金表复制为全家预算。','每次交不可退定金前保留学校报价、退款政策、项目资格和当日移民规则；先留退出资金。']))
body+=sec('family','4.5 家属、实习与学期工作',p('配偶是否可以工作取决于主申请人所持身份、课程层级/长度、工作类别及剩余许可等现行联邦条件。普通两年学院文凭不能默认给配偶开放工签。毕业转工签后也不能默认所有配偶均符合。'+c('spousestudent')+c('spouseworker'))+p('课程有实习不代表可以不检查工作授权、体检、弱势群体背景审查、疫苗和雇主条件。学校实习也不保证毕业后全职聘用；移民经验是否可计必须重新按具体类别核。'+c('school-nurse-entry')+c('school-ece-entry')+c('abos')+c('cec')))
