body=sec('risk','7.1 对外不能承诺什么',table(['错误说法','可以核实的表达','依据'],[['“300分就能移民阿省”','只是省快速通道最低资格之一；还需联邦资格及省邀请。',c('abee')],['“乡村可从中国去做任何低技能工作”','阿省以外申请者目前只接受0—3级；在阿省有效工签者才可研究0—5级。',c('abrural')],['“旅游同雇主半年必提名”','先核指定工签、协会/行业、职业、语言、雇主，再面对邀请与容量。',c('abtour')],['“护士、护工、幼教都是医疗快速通道”','九类专业范围有限；职业执照与雇主同样必须满足。',c('abhealth')],['“毕业工签合格就一定能省提名”','省级毕业生学历要求、经验、专业关系与省选择另核。',c('abos')],['“最低投资就是买身份的总价”','是可验证投资下限，还包括净资产、生活、经营风险与实际履约。',c('abbiz')],['“政府有配额就能算你成功率”','配额、库存、候选池、邀请、联邦批准不同口径，不能据此承诺个体概率。',c('processing')]]))
