body+=sec('conflicts','7.3 保留资料差异，避免把旧信息说成现行事实',table(['差异','处理方式'],[['医疗网页仍写旧护理监管名称','阿省监管总表与健康护理助理公告说明2026监管变化；保留旧网页原件，正文使用当前解释。'],['学校网页模板同时含合格/不合格弹窗','读取项目顶部实际国际招生/项目代码标识，不能以隐藏弹窗通用文字反推该项目；酒店综合方向实际标为不合格。'],['科技旧页面与当前统一工人流程','统一意向表达/邀请说明作为操作入口；有歧义先取得官方澄清，保存版本。'],['全国职业分类与阿省执照','全国一般就业要求作为职业说明；实际许可须按阿省监管机构当前规定；不声称110个职业所有执照个案均已审定。'],['课程网页与未来学年报价','当前公开估费按学年和学生类型标注；未来费用、名额及个人豁免以书面结果更新。']])+c('health-regulators')+c('school-hospitality')+c('worker-apply')+c('noc-elements'))
